import{_ as t,o as d,c as o,a2 as a}from"./chunks/framework.BN3Eol-0.js";const m=JSON.parse('{"title":"Backfill: UX decisions made before the UXD series","description":"","frontmatter":{},"headers":[],"relativePath":"uxs/decisions/BACKFILL.md","filePath":"uxs/decisions/BACKFILL.md"}'),s={name:"uxs/decisions/BACKFILL.md"};function n(r,e,i,c,l,h){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="backfill-ux-decisions-made-before-the-uxd-series" tabindex="-1">Backfill: UX decisions made before the UXD series <a class="header-anchor" href="#backfill-ux-decisions-made-before-the-uxd-series" aria-label="Permalink to &quot;Backfill: UX decisions made before the UXD series&quot;">​</a></h1><p>Extracted on 2026-11-11 from <code>IA.md</code>, the UXS documents, AGENTS.md, the design system doc, the ADRs and the operator&#39;s operator notes. History, not re-decided: each row says what was decided and where it is stated. A row becomes a full UXD only when the decision is revisited.</p><p><strong>How to read it.</strong> <strong>Kind</strong> is one of <code>decided</code>, <code>superseded</code> and <code>rejected</code>. A <code>superseded</code> row names the record or row that replaced it; &quot;partly superseded&quot; means a later record changed part of the rule and the row stays <code>decided</code>. <strong>Who / ref</strong> is <code>operator</code> when the source says the operator made the call (with the dated operator note), then any ADR, PRD or commit the source cites; it is <code>spec</code> when the source gives neither. <strong>Date</strong> is copied from the source; <code>undated</code> means the source gives none (the date is not invented). <strong>Where stated</strong> is file and line (or section) at commit <code>9fdf4cc4a6b</code>. &quot;Conflicts with&quot; appears only where the code or another document was read and disagrees; the ids SC-1 to SC-5 are the spec-to-code mismatches in <a href="./../UXS-000-orrery-ux-architecture#spec-to-code-mismatches-open">UXS-000</a>. Operator notes are the operator&#39;s private working notes (cited by name and date, with no path), quoted for the decision and its date only.</p><table tabindex="0"><thead><tr><th>#</th><th>Date</th><th>Decision (one sentence, the rule as decided)</th><th>Kind</th><th>Who / ref</th><th>Where stated</th></tr></thead><tbody><tr><td>B-001</td><td>undated</td><td>One persistent top nav bar on every screen, 52 px high, with the wordmark at left, the screen links centred and screen-specific controls at right.</td><td>decided · conflicts with <code>tokens.css</code> (<code>--nav-bar-height: 60px</code>), SC-1</td><td>spec</td><td><code>IA.md</code> §topbar-patterns lines 50–55, §shell-regions line 179; the earliest stated date for IA.md is its first version, April 2026 (changelog, line 304)</td></tr><tr><td>B-002</td><td>2026-04-28</td><td>Mobile-first: base CSS targets small screens (design at 375 px first, desktop is progressive enhancement), the detail panel is a bottom sheet on small screens and a right drawer on large, touch targets are at least 44×44 px, breakpoints 768 and 1024 px.</td><td>decided · desktop drawer width: the docs now say 400 px, as <code>tokens.css</code> (<code>--panel-width: 400px</code>); SC-2 closed 2026-11-15</td><td>ADR-018</td><td><code>docs/adr/ADR-018.md</code> lines 2–3 and §Decision; <code>AGENTS.md</code> §Mobile-first rules lines 494–508</td></tr><tr><td>B-003</td><td>2026-04-29</td><td>Accessibility tier 1: reduced motion stops unsolicited motion on every canvas screen, nav links are real anchors, a 2 px brand-blue <code>:focus-visible</code> ring is global, detail panels are <code>&lt;aside&gt;</code> landmarks (not dialogs) and focus moves to the close button on open.</td><td>decided</td><td>ADR-025</td><td><code>docs/adr/ADR-025.md</code> lines 3–4 and §Decision</td></tr><tr><td>B-004</td><td>undated</td><td>Teal <code>#4ecdc4</code> is the secondary accent (active status, Earth orbit regime, confirmation, CAPCOM and &quot;viable&quot; colours, introductory link tier).</td><td>superseded by UXD-001 · conflicts with UXD-001 and <code>tokens.css</code> still defining <code>--color-teal</code>, SC-4</td><td>spec</td><td><code>05_Design_System.md</code> line 48, <code>IA.md</code> lines 198 and 213, <code>AGENTS.md</code> line 720, <code>UXS-002.md</code> lines 38–40, <code>UXS-003.md</code> lines 42 and 89; the earliest stated date for IA.md is its first version, April 2026 (changelog, line 304)</td></tr><tr><td>B-005</td><td>undated</td><td>Dimmed text and labels sit at 25–35 % white (<code>text-dim</code>).</td><td>superseded by UXD-002 (labels at 60 %) · conflicts with <code>tokens.css</code> (<code>--color-text-dim: 0.6</code>), SC-3</td><td>spec</td><td><code>05_Design_System.md</code> line 51, <code>IA.md</code> line 203; the earliest stated date for IA.md is its first version, April 2026 (changelog, line 304)</td></tr><tr><td>B-006</td><td>undated</td><td>Crimson Pro is the editorial face: panel overviews and leads in italic Crimson, at 13–14 px and 60 %.</td><td>superseded by UXD-002 (upright Space Mono leads; italic only for quotes and captions at 14 px or more)</td><td>spec</td><td>read as the pre-A1 state in <code>docs/wip/2026-11-11-ux-feedback-plan.md</code> line 327 and <code>docs/wip/2026-11-11-slice-A1-brief.md</code> lines 18–20 and 30–31 (&quot;Crimson always italic line is wrong after A1&quot;)</td></tr><tr><td>B-007</td><td>undated</td><td>Honest about gaps: data-quality badges, reconstruction notes and placeholder states are first-class design elements; never hide a gap.</td><td>decided</td><td>spec</td><td><code>docs/concept/05_Design_System.md</code> line 29</td></tr><tr><td>B-008</td><td>undated</td><td>Agency and logo marks use &quot;fallback always visible, real image on top&quot;: the abbreviation is always shown and the real logo loads over it, so it never breaks offline.</td><td>decided</td><td>spec</td><td><code>05_Design_System.md</code> lines 279–288</td></tr><tr><td>B-009</td><td>2026-05-06</td><td>Imagery is sourced agency-first at build time; the entity&#39;s own operator (agency) page is the first intro link on a non-US entity.</td><td>decided</td><td>ADR-046, ADR-051</td><td><code>docs/adr/ADR-046.md</code> line 3; <code>AGENTS.md</code> line 993</td></tr><tr><td>B-010</td><td>2026-05-07</td><td>Science, fleet, station and spacecraft diagrams are committed hand-authored SVG source files; AI tools do not generate them.</td><td>decided</td><td>ADR-035</td><td><code>docs/adr/ADR-035.md</code> lines 3–4 and §Decision; <code>AGENTS.md</code> line 1008</td></tr><tr><td>B-011</td><td>2026-05-07</td><td>The <code>?</code> chip: click navigates to the <code>/science</code> section, hover shows a native tooltip on desktop only; no popover or modal.</td><td>decided</td><td>ADR-036</td><td><code>docs/adr/ADR-036.md</code> §Decision</td></tr><tr><td>B-012</td><td>2026-05-07</td><td>A modal popover on <code>?</code> click is not used (it loses context on mobile).</td><td>rejected</td><td>ADR-036 (RFC-011 OQ-3 Option C)</td><td><code>docs/adr/ADR-036.md</code> §Decision</td></tr><tr><td>B-013</td><td>2026-05-09</td><td>The Science Lens is one master state, the attribute <code>data-science-lens</code> on <code>&lt;html&gt;</code>; the nav button is the only UI that flips it, it is not persisted and resets to off on every load.</td><td>decided</td><td>ADR-055</td><td><code>docs/adr/ADR-055.md</code> lines 3–4 and §Decision</td></tr><tr><td>B-014</td><td>2026-05-15</td><td>A flown vehicle&#39;s hero is a photograph and any concept slot says so in its title and alt text; planned-only vehicles are exempt by <code>status</code>, a vehicle with no photograph carries an <code>artistic_impressions</code> waiver (amended 2026-11-13: the <code>artistic-impression: true</code> flag of 2026-05-15 never existed in code; <code>validate-image-depiction</code> enforces the rule).</td><td>decided; amended 2026-11-13</td><td>ADR-053, ADR-046</td><td><code>docs/adr/ADR-053.md</code> lines 4 and 87; <code>AGENTS.md</code> line 1007</td></tr><tr><td>B-015</td><td>2026-05-30</td><td><code>/moon</code> and <code>/mars</code> share one <code>SurfaceScene</code>; differences between bodies are justified per body or rejected as drift.</td><td>decided</td><td>ADR-072</td><td><code>docs/adr/ADR-072.md</code> lines 3–4 and §Decision</td></tr><tr><td>B-016</td><td>undated</td><td>Every committed image ends up as a row on <code>/credits</code> (and every outbound learn link on <code>/library</code>) through the provenance manifests; otherwise the work is not done.</td><td>decided</td><td>ADR-046, ADR-047, ADR-051</td><td><code>AGENTS.md</code> line 1003</td></tr><tr><td>B-017</td><td>August 2026 (IA changelog v1.2)</td><td>The Physics Lab is one card model with three views (Notebook, Focus, Canvas); the Lab colour discipline is teal for figure and selection, gold for explanation, Mars red for fail-honest.</td><td>decided</td><td>UXS-015, PRD-033, RFC-037</td><td><code>IA.md</code> §lab lines 37–46; <code>UXS-015.md</code> §&quot;The one idea&quot;</td></tr><tr><td>B-018</td><td>2026-08</td><td>The nav is grouped: Home, Explore ▾, Worlds ▾, Fly, Plan, Catalog ▾, Learn ▾; Explore is scope (the scale shells), Worlds is bodies (only bodies with a dedicated <code>SurfaceScene</code>), and <code>/explore</code> itself is not renamed.</td><td>decided · IA line 88 says &quot;six slots, two standalone links&quot; while the table lists seven slots and three links (Home, Fly, Plan)</td><td>spec</td><td><code>IA.md</code> §nav-groups lines 85–118</td></tr><tr><td>B-019</td><td>2026-08</td><td>On TV each nav group renders as a single link to its big-box hub (<code>/explore/hub</code>, <code>/worlds</code>, <code>/catalog</code>, <code>/learn</code>) because a dropdown is unusable with a D-pad.</td><td>decided</td><td>spec</td><td><code>IA.md</code> §nav-groups lines 113–116</td></tr><tr><td>B-020</td><td>2026-08</td><td>The landing shows the whole nav tree unpacked and sectioned, each leaf its own card; the nav stays compact, the landing reveals breadth.</td><td>decided</td><td>spec</td><td><code>IA.md</code> §home-cards lines 121–152</td></tr><tr><td>B-021</td><td>2026-08</td><td>Nav width: between 641 and 1319 px the link padding tightens from 10 px to 6 px so wide locales (fr, es, pt-BR, ru) do not overflow.</td><td>decided</td><td>spec (measured 2026-08)</td><td><code>IA.md</code> lines 143–150</td></tr><tr><td>B-022</td><td>2026-08</td><td>Consolidating Fly and Plan into one nav group was considered and not done: both are core features that warrant top-level prominence.</td><td>rejected</td><td>spec</td><td><code>IA.md</code> lines 147–150</td></tr><tr><td>B-023</td><td>2026-08-08 (the date in the UXS-016 footer; the PRD-034 decision date was not read)</td><td>The scale ladder is the one scale control for the whole arc, extended from 4 to 8 rungs (Cosmic Web to Solar System, outermost first), direction A.</td><td>decided</td><td>PRD-034 §UX, UXS-016</td><td><code>UXS-016.md</code> §1 and its footer line</td></tr><tr><td>B-024</td><td>undated</td><td>Every explore screen carries an always-visible, always-clickable breadcrumb (&quot;you are here&quot;); it is non-negotiable because teleporting makes orientation the scarcest resource.</td><td>decided</td><td>UXS-014, PRD-030</td><td><code>UXS-014.md</code> §&quot;The one rule: you always know where you are&quot; (lines 12–14)</td></tr><tr><td>B-025</td><td>undated</td><td>A signature interaction moment gets a prototype or visual anchor before it is built (&quot;visual anchor before UX commit&quot;).</td><td>decided</td><td>UXS-014, UXS-016, UXS-015</td><td><code>UXS-014.md</code> line 4, <code>UXS-016.md</code> line 6</td></tr><tr><td>B-026</td><td>2026-08-31</td><td>The Lab shows one goal-level &quot;grand hero&quot; flight-map canvas per capstone or milestone goal, above the notebook steps.</td><td>decided</td><td>ADR-090 (operator-directed)</td><td><code>docs/adr/ADR-090.md</code> line 3 and §Decision</td></tr><tr><td>B-027</td><td>2026-10-16</td><td>The boxes in the UXS documents were not maintained after implementation and are not a record of what shipped; shipped behaviour is read from TA.md and CHANGELOG.md.</td><td>decided</td><td>spec</td><td><code>UXS-001.md</code> line 93 and the same note in UXS-002 to UXS-006 and UXS-013</td></tr><tr><td>B-028</td><td>2026-10-17</td><td>In each locale a thing has one name everywhere: gallery and entity pages set the canonical form first, then essays, science articles and captions follow it, inflected by grammar.</td><td>decided</td><td>operator, 2026-10-17 (operator note <code>one-name-per-language</code>)</td><td><code>docs/guides/i18n-translation-strategy.md</code> §3.3 (as cited by the note)</td></tr><tr><td>B-029</td><td>2026-10-17</td><td>A name shows in its original language and script in that origin&#39;s locale (ru Союз, zh 神舟, ar for Iranian names) and in English in every other locale; agencies use their own-language form in their own locale and keep the acronym elsewhere (2026-10-18).</td><td>decided</td><td>operator, 2026-10-17 and 2026-10-18 (operator note <code>names-origin-language-rule</code>)</td><td><code>src/lib/name-origins.js</code> and <code>scripts/i18n-tools/native-terms.json</code> (as cited by the note)</td></tr><tr><td>B-030</td><td>2026-10-17</td><td>Science, geography and astronomy terms and person names are fully native in every locale, written as that country&#39;s universities and agencies write them (checked on native pages when unsure).</td><td>decided</td><td>operator, 2026-10-17 (operator note <code>science-terms-native</code>)</td><td><code>scripts/i18n-tools/native-terms.json</code> (as cited by the note)</td></tr><tr><td>B-031</td><td>2026-10-29</td><td>A change to user-facing text that carries a number or other fact is validated and changed in all 14 locales, not only en-US.</td><td>decided</td><td>operator, 2026-10-29 (operator note <code>numbers-in-all-locales</code>)</td><td><code>messages/*.json</code> and <code>i18n-src/&lt;locale&gt;/</code> (as cited by the note)</td></tr><tr><td>B-032</td><td>2026-11-06</td><td>Art of Starship never shows NASA alone: the SpaceX mark is main, NASA only where it commissioned the craft (Starship HLS), or no logos at all.</td><td>decided</td><td>operator, 2026-11-06 (operator note <code>starship-logos</code>)</td><td><code>docs/anatomy-art-runbook.md</code> golden rule 6 (as cited by the note)</td></tr><tr><td>B-033</td><td>2026-11-08</td><td>Hero images on the explore pages, above all the planets, must stay visually consistent with each other.</td><td>decided</td><td>operator, 2026-11-08 (operator note <code>explore-heroes-consistent</code>)</td><td><a href="./UXD-029-planet-heroes-whole-disc-on-black">UXD-029</a>; AGENTS.md &quot;Planet heroes&quot;</td></tr><tr><td>B-034</td><td>2026-11-09</td><td>No cyan or teal in UI states (annotation ring hover), landing-site dioramas or reference maps; use the muted blue <code>#889fe7</code> beside the yellow and amber.</td><td>decided · partly superseded by UXD-001 (UI accent is <code>#5070ff</code>); the code keeps <code>#889fe7</code> for the surface scenes (<code>surface-markers.ts</code> line 45)</td><td>operator, 2026-11-09 (operator note <code>no-cyan</code>)</td><td>operator note; <code>docs/wip/2026-11-09-0.9.9-redesign.md</code> lines 7–11</td></tr><tr><td>B-035</td><td>2026-11-09</td><td>Science diagrams (the cyan-on-navy <code>/science</code> style) and the Lab goal art are not affected by the no-cyan rule and keep their style.</td><td>decided · carried into UXD-001 (&quot;for now&quot;, end-check)</td><td>operator, 2026-11-09</td><td>operator note <code>no-cyan</code>; <code>docs/wip/2026-11-09-0.9.9-redesign.md</code> lines 18–22</td></tr><tr><td>B-036</td><td>2026-11-09</td><td>The app&#39;s own marker hover, the ACTIVE status tone and the route lines move from teal to <code>#889fe7</code>, approved after before/after screenshots.</td><td>decided · partly superseded by UXD-001 for the rest of the UI</td><td>operator, 2026-11-09 (operator note <code>no-cyan</code>; commit <code>3757791a334</code>)</td><td><code>docs/wip/2026-11-09-0.9.9-redesign.md</code> lines 8–10</td></tr><tr><td>B-037</td><td>2026-11-09</td><td>0.9.9 is the arc that replaces the site-wide teal brand accent, mocked up first; 0.9.8 leaves it alone.</td><td>superseded by UXD-001 (merged into the 2026-11-11 feedback list, plan lines 5 and 44)</td><td>operator, 2026-11-09 (operator note <code>099-redesign</code>)</td><td><code>docs/wip/2026-11-09-0.9.9-redesign.md</code> line 3</td></tr><tr><td>B-038</td><td>2026-11-11</td><td>The surface composer ends in an OutputPass and one <code>HOVER_BLUE</code> applies on every quality tier (commit <code>8e9a7c8d1d9</code>); the before/after shots of the surface fix were &quot;sent for approval&quot;, and no approval is recorded.</td><td>decided · extended to every composer by UXD-004</td><td>commit <code>8e9a7c8d1d9</code> (surface fix, plan line 456: &quot;sent for approval&quot;); the extension &quot;one OutputPass per composer&quot; is the operator&#39;s decision, 2026-11-11 (plan lines 457–458)</td><td><code>docs/wip/2026-11-09-0.9.9-redesign.md</code> lines 27–33; plan lines 456–458</td></tr><tr><td>B-039</td><td>2026-11-10</td><td>No staging tier; GitHub Pages serves only the docs.</td><td>superseded by UXD-005 (recorded there in full)</td><td>operator, 2026-11-10; ADR-097</td><td><code>docs/adr/ADR-097.md</code> line 3</td></tr></tbody></table><h2 id="notes-on-what-this-ledger-does-not-contain" tabindex="-1">Notes on what this ledger does not contain <a class="header-anchor" href="#notes-on-what-this-ledger-does-not-contain" aria-label="Permalink to &quot;Notes on what this ledger does not contain&quot;">​</a></h2><ul><li><strong>IA and UXS rules with no date and no stated decider.</strong> The UXS documents are mostly &quot;Draft v0.1&quot; specifications; their individual rules (card layouts, panel anatomy, HUD values) carry no decision date. They are the current spec, not history, and are not enumerated here.</li><li><strong>Decisions only in the working plan.</strong> The 2026-11-11 answers (Q1, Q2 and the clarifications) are the UXDs, not backfill.</li><li><strong>Open questions</strong> (D7, Q3 to Q6) are listed in <a href="./../UXS-000-orrery-ux-architecture#open">UXS-000 §Open</a>, not here.</li><li><strong>ADRs that are architecture, not UX</strong> (for example ADR-001 to ADR-017 on stack, ADR-063 to ADR-071 on deploy) are not backfilled; the UX-relevant ones are rows above. The ADRs were found by title scan, not read end to end; only the ADRs cited in the rows were read for their decision text.</li></ul>',6)])])}const u=t(s,[["render",n]]);export{m as __pageData,u as default};
